parameters.jsCode:
const fs = require('fs');
const LOG_DIR = './logs';
function appendLog(event) {
  fs.mkdirSync(LOG_DIR, { recursive: true });
  fs.appendFileSync(LOG_DIR + '/runs.jsonl', JSON.stringify({ ts: new Date().toISOString(), implementation: 'n8n', ...event }) + '\n');
}

const runCtx = $('Build Evidence Records').first().json;
const clientRunId = runCtx._client_run_id;
const runId = runCtx._run_id || runCtx.run_id;

const agentItem = $input.first().json;
const artifact = agentItem.output || agentItem;

const evidenceSet = $('Build Evidence Records').first().json.evidence || [];
const validIds = new Set(evidenceSet.map(e => e.evidence_id));

// Anything that looks like a citation counts, well-formed or not: an invented "EV-CNHA" must be caught
// here, not three nodes later (it was, in execution 28). Same rule as CrewAI's drop_invented_ids: an id
// not in the evidence set is removed, never remapped to a near-miss real id; a cited field left with no
// evidence falls to basis "inference". Lists that must keep an id (a theme's supporting_evidence_ids, a
// derived field's derived_from_evidence_ids) are only trimmed while a real id remains; otherwise the run
// stops here with the reason.
const EV_LIKE = /^EV-/;
const droppedIds = [];

function repair(node, path) {
  if (Array.isArray(node)) { node.forEach((v, i) => repair(v, `${path}[${i}]`)); return; }
  if (!node || typeof node !== 'object') return;
  if (Array.isArray(node.evidence_ids)) {
    const kept = node.evidence_ids.filter(id => validIds.has(id));
    if (kept.length !== node.evidence_ids.length) {
      const downgraded = node.basis === 'evidence' && kept.length === 0;
      droppedIds.push({ path, dropped: node.evidence_ids.filter(id => !validIds.has(id)), basis_downgraded_to_inference: downgraded });
      node.evidence_ids = kept;
      if (downgraded) node.basis = 'inference';
    }
  }
  for (const key of ['supporting_evidence_ids', 'derived_from_evidence_ids']) {
    const ids = node[key];
    if (!Array.isArray(ids)) continue;
    const kept = ids.filter(id => validIds.has(id));
    if (kept.length && kept.length !== ids.length) {
      droppedIds.push({ path: path ? `${path}.${key}` : key, dropped: ids.filter(id => !validIds.has(id)), basis_downgraded_to_inference: false });
      node[key] = kept;
    }
  }
  for (const key of Object.keys(node)) repair(node[key], path ? `${path}.${key}` : key);
}

repair(artifact, '');

const referenced = [];

function walk(node, path) {
  if (node === null || node === undefined) return;
  if (typeof node === 'string') {
    if (EV_LIKE.test(node)) {
      referenced.push({ id: node, path });
    }
    return;
  }
  if (Array.isArray(node)) {
    node.forEach((item, i) => walk(item, `${path}[${i}]`));
    return;
  }
  if (typeof node === 'object') {
    for (const key of Object.keys(node)) {
      walk(node[key], path ? `${path}.${key}` : key);
    }
  }
}

walk(artifact, '');

const uniqueReferencedIds = [...new Set(referenced.map(r => r.id))];
const invalidReferences = referenced.filter(r => !validIds.has(r.id));
const invalidUniqueIds = [...new Set(invalidReferences.map(r => r.id))];
const validUniqueIds = uniqueReferencedIds.filter(id => validIds.has(id));

const coveragePercent = uniqueReferencedIds.length > 0
  ? Math.round((validUniqueIds.length / uniqueReferencedIds.length) * 1000) / 10
  : null;

if (invalidReferences.length) {
  appendLog({
    event_type: 'validation_gate', client_run_id: clientRunId, run_id: runId,
    node: 'Validate Evidence Coverage', gate: 'evidence_coverage', status: 'error',
    invalid_unique_ids: invalidUniqueIds, dropped_ids: droppedIds,
    error: `unrepairable citation(s) not in the evidence set: ${invalidReferences.map(r => `${r.id} at ${r.path}`).join('; ')}`,
  });
  throw new Error(`Validate Evidence Coverage: citation(s) not in the evidence set that cannot be removed safely: ${invalidReferences.map(r => `${r.id} at ${r.path}`).join('; ')}`);
}

// Guide requires "Number of invalid or broken URLs" in the run record. We only
// validate URL syntax/protocol here (no live HTTP check) -- a live check would
// burn extra requests against the brief's own search-call budget.
// n8n's Code node sandbox does not expose the global URL class, so this uses
// a regex check instead of new URL() -- a real http(s) URL with a dotted host.
const HTTP_URL_RE = /^https?:\/\/([\w-]+\.)+[a-z]{2,}(:\d+)?(\/[^\s]*)?$/i;
let invalidUrlCount = 0;
for (const e of evidenceSet) {
  if (typeof e.source_url !== 'string' || !HTTP_URL_RE.test(e.source_url)) {
    invalidUrlCount++;
  }
}

const validation = {
  evidence_set_size: validIds.size,
  total_evidence_id_references: referenced.length,
  unique_evidence_ids_referenced: uniqueReferencedIds.length,
  invalid_evidence_id_references: invalidReferences,
  invalid_unique_ids: invalidUniqueIds,
  all_references_valid: invalidReferences.length === 0,
  dropped_ids: droppedIds,
  valid_reference_coverage_percent: coveragePercent,
  invalid_url_count: invalidUrlCount,
};

appendLog({
  event_type: 'validation_gate',
  client_run_id: clientRunId,
  run_id: runId,
  node: 'Validate Evidence Coverage',
  gate: 'evidence_coverage',
  status: validation.all_references_valid ? 'ok' : 'error',
  evidence_coverage_percent: coveragePercent,
  invalid_unique_ids: invalidUniqueIds,
  dropped_id_count: droppedIds.reduce((n, d) => n + d.dropped.length, 0),
  invalid_url_count: invalidUrlCount,
});

appendLog({
  event_type: 'agent_start',
  client_run_id: clientRunId,
  run_id: runId,
  node: 'Strategy Agent',
  agent: 'Strategy Agent',
  model: 'gpt-5-mini',
  provider: 'openai',
  status: 'ok',
});

return [{
  json: {
    artifact,
    validation,
    _client_run_id: clientRunId,
    _run_id: runId,
    _t_strategy_agent_start: new Date().toISOString(),
  },
}];

