const initCtx = $('Init Run Log').first().json;
const clientRunId = initCtx._client_run_id;
const pipelineStartedAt = initCtx._pipeline_started_at;

const plan = $('Head Planner').first().json.output;
const runId = (plan && plan.run_id) || clientRunId;
const budget = (plan && plan.budget) || {};

const evidenceCtx = $('Build Evidence Records').first().json;
const evidenceSet = evidenceCtx.evidence || [];
const toolCallsPlanned = evidenceCtx.tool_calls_planned || 0;
const toolCallsExecuted = evidenceCtx.tool_calls_executed || 0;

const evidenceCoverage = $('Validate Evidence Coverage').first().json.validation || {};
const strategyGrounding = $('Validate Strategy Grounding').first().json.validation || {};

const docsWriter = $input.first().json;

// Provider rate-limit (HTTP 429) errors that reached n8n's console during this run, read from the server
// log between the offset recorded by Init Run Log and now. This is NOT a retry count: n8n does not expose
// per-node attempt counts to workflow code, and a retry that succeeds silently leaves no log line, so this
// undercounts. null means the log was unavailable.
let rateLimitErrorsLogged = null;
if (typeof initCtx._server_log_offset === 'number') {
  try {
    const fd = fs.openSync('./logs/n8n_server.log', 'r');
    const size = fs.fstatSync(fd).size;
    if (size >= initCtx._server_log_offset) {
      const buf = Buffer.alloc(size - initCtx._server_log_offset);
      fs.readSync(fd, buf, 0, buf.length, initCtx._server_log_offset);
      rateLimitErrorsLogged = (buf.toString('utf8').match(/^429 /gm) || []).length;
    }
    fs.closeSync(fd);
  } catch (e) { /* leave null */ }
}

const nowIso = new Date().toISOString();
const totalDurationMs = new Date(nowIso) - new Date(pipelineStartedAt);

const rqIds = new Set(((plan && plan.research_questions) || []).map(rq => rq.id));
const answeredRqIds = new Set(evidenceSet.map(e => e.research_question_id).filter(Boolean));
const researchQuestionsAnswered = [...answeredRqIds].filter(id => rqIds.has(id)).length;

const HTTP_URL_RE = /^https?:\/\/([\w-]+\.)+[a-z]{2,}(:\d+)?(\/[^\s]*)?$/i;
let invalidUrlCount = evidenceCoverage.invalid_url_count;
if (typeof invalidUrlCount !== 'number') {
  invalidUrlCount = 0;
  for (const e of evidenceSet) {
    if (typeof e.source_url !== 'string' || !HTTP_URL_RE.test(e.source_url)) {
      invalidUrlCount++;
    }
  }
}

const issues = [];
const maxWallClockMs = (budget.max_wall_clock_minutes || 12) * 60 * 1000;
const overTime = totalDurationMs > maxWallClockMs;
if (overTime) issues.push(`Wall-clock time ${Math.round(totalDurationMs / 1000)}s exceeded budget of ${budget.max_wall_clock_minutes || 12} minutes.`);

const maxSearchCalls = budget.max_search_calls || 40;
const overCalls = toolCallsExecuted > maxSearchCalls;
if (overCalls) issues.push(`Tool calls executed (${toolCallsExecuted}) exceeded budget of ${maxSearchCalls}.`);

const droppedCount = (evidenceCoverage.dropped_ids || []).reduce((n, d) => n + d.dropped.length, 0);
if (droppedCount) issues.push(`${droppedCount} invented evidence id(s) removed`);
if (invalidUrlCount > 0) issues.push(`${invalidUrlCount} evidence source_url value(s) failed URL validation.`);
if (!evidenceCoverage.all_references_valid) issues.push('Evidence coverage validation did not pass (should have been caught upstream).');
if (!strategyGrounding.clean) issues.push('Strategy grounding validation did not pass (should have been caught upstream).');

if (!docsWriter || typeof docsWriter.docs_writer_status !== 'string' || !docsWriter.artifact) {
  appendLog({
    event_type: 'run_complete',
    client_run_id: clientRunId,
